import 'dart:convert';

import 'package:google_maps_flutter/google_maps_flutter.dart';

/// Realistic GO motorcycle marker used by the delegate live-location map.
/// The compact PNG is embedded as base64 so the same marker renders on
/// Android, iOS and Flutter Web without an extra binary repository upload.
class DelegateMotorcycleMarker {
  const DelegateMotorcycleMarker._();

  static BitmapDescriptor create() {
    return BitmapDescriptor.fromBytes(base64Decode(_pngBase64));
  }

  static const String _pngBase64 =
      '';
}
